674	package net.officefloor.hq.app.setting;
675	
676	import jakarta.validation.Valid;
677	import java.math.BigDecimal;
678	import java.time.LocalDate;
679	import java.time.format.DateTimeParseException;
680	import java.util.LinkedHashMap;
681	import java.util.Map;
682	import java.util.Set;
683	import java.util.regex.Pattern;
684	import net.officefloor.plugin.variable.Out;
685	import org.springframework.web.bind.annotation.RequestBody;
686	
687	public class ValidateSettingsRequest {
688	
689	    /** 0.00 or more, with at most two decimals. */
690	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,13}(\\.\\d{1,2})?|\\.\\d{1,2}");
691	
692	    /** A percent: 0.00 or more, with at most two decimals. */
693	    private static final Pattern PERCENT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?|\\.\\d{1,2}");
694	
695	    /** The grades terms can be set for. */
696	    private static final Set<String> GRADES = Set.of("A", "B", "C");
697	
698	    /** 0 or more whole days. */
699	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
700	
701	    public void validate(@RequestBody @Valid SettingsRequest request, Out<ClerkLimit> limit, Out<Floor> floor,
702	            Out<Terms> terms, Out<LatePct> latePct, Out<PolicyDate> policyDate,
703	            Out<PeriodNumberingFrom> periodNumberingFrom, Out<GradeTerms> gradeTerms, Out<Cap> cap)
704	            throws InvalidSettingException {
705	        limit.set(clerkLimit(request.clerkLimit()));
706	        floor.set(floor(request.floor()));
707	        terms.set(terms(request.terms()));
708	        latePct.set(latePct(request.latePct()));
709	        policyDate.set(policyDate(request.policyDate()));
710	        periodNumberingFrom.set(periodNumberingFrom(request.periodNumberingFrom()));
711	        gradeTerms.set(gradeTerms(request.gradeTerms()));
712	        cap.set(cap(request.cap()));
713	    }
714	
715	    private static Cap cap(String requested) throws InvalidSettingException {
716	        if (requested == null) {
717	            return new Cap(false, null);
718	        }
719	        String value = requested.trim();
720	        if (value.isEmpty()) {
721	            return new Cap(true, null);
722	        }
723	        if (!AMOUNT.matcher(value).matches()) {
724	            throw new InvalidSettingException("The cap must be 0.00 or more, with at most two decimals, or blank.");
725	        }
726	        return new Cap(true, new BigDecimal(value).setScale(2));
727	    }
728	
729	    private static ClerkLimit clerkLimit(String requested) throws InvalidSettingException {
730	        if (requested == null) {
731	            return new ClerkLimit(false, null);
732	        }
733	        String value = requested.trim();
734	        if (value.isEmpty()) {
735	            return new ClerkLimit(true, null);
736	        }
737	        if (!AMOUNT.matcher(value).matches()) {
738	            throw new InvalidSettingException("The clerk limit must be 0.00 or more, with at most two decimals, or blank.");
739	        }
740	        return new ClerkLimit(true, new BigDecimal(value).setScale(2));
741	    }
742	
743	    private static Terms terms(String requested) throws InvalidSettingException {
744	        if (requested == null) {
745	            return new Terms(null);
746	        }
747	        String value = requested.trim();
748	        if (value.isEmpty()) {
749	            return new Terms(SettingRepository.DEFAULT_TERMS);
750	        }
751	        if (!DAYS.matcher(value).matches()) {
752	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more, or blank.");
753	        }
754	        return new Terms(Integer.parseInt(value));
755	    }
756	
757	    private static GradeTerms gradeTerms(Map<String, String> requested) throws InvalidSettingException {
758	        Map<String, Integer> terms = new LinkedHashMap<>();
759	        if (requested == null) {
760	            return new GradeTerms(terms);
761	        }
762	        for (String grade : requested.keySet().stream().sorted().toList()) {
763	            if (!GRADES.contains(grade)) {
764	                throw new InvalidSettingException("Terms can only be set for grade A, B or C.");
765	            }
766	            String value = requested.get(grade) == null ? "" : requested.get(grade).trim();
767	            if (value.isEmpty()) {
768	                terms.put(grade, null);
769	            } else if (!DAYS.matcher(value).matches()) {
770	                throw new InvalidSettingException("The terms for a grade must be a whole number of days, 0 or more, or blank.");
771	            } else {
772	                terms.put(grade, Integer.parseInt(value));
773	            }
774	        }
775	        return new GradeTerms(terms);
776	    }
777	
778	    private static LatePct latePct(String requested) throws InvalidSettingException {
779	        if (requested == null) {
780	            return new LatePct(null);
781	        }
782	        String value = requested.trim();
783	        if (value.isEmpty()) {
784	            return new LatePct(SettingRepository.DEFAULT_LATE_PCT);
785	        }
786	        if (!PERCENT.matcher(value).matches()) {
787	            throw new InvalidSettingException("The late percent must be 0.00 or more, with at most two decimals, or blank.");
788	        }
789	        return new LatePct(new BigDecimal(value).setScale(2));
790	    }
791	
792	    private static PolicyDate policyDate(String requested) throws InvalidSettingException {
793	        if (requested == null) {
794	            return new PolicyDate(false, null);
795	        }
796	        String value = requested.trim();
797	        if (value.isEmpty()) {
798	            return new PolicyDate(true, null);
799	        }
800	        try {
801	            return new PolicyDate(true, LocalDate.parse(value));
802	        } catch (DateTimeParseException e) {
803	            throw new InvalidSettingException("The policy date must be a date (yyyy-MM-dd), or blank.");
804	        }
805	    }
806	
807	    private static PeriodNumberingFrom periodNumberingFrom(String requested) throws InvalidSettingException {
808	        if (requested == null) {
809	            return new PeriodNumberingFrom(false, null);
810	        }
811	        String value = requested.trim();
812	        if (value.isEmpty()) {
813	            return new PeriodNumberingFrom(true, null);
814	        }
815	        try {
816	            return new PeriodNumberingFrom(true, LocalDate.parse(value));
817	        } catch (DateTimeParseException e) {
818	            throw new InvalidSettingException("The period numbering from date must be a date (yyyy-MM-dd), or blank.");
819	        }
820	    }
821	
822	    private static Floor floor(String requested) throws InvalidSettingException {
823	        if (requested == null) {
824	            return new Floor(null);
825	        }
826	        String value = requested.trim();
827	        if (value.isEmpty()) {
828	            return new Floor(SettingRepository.DEFAULT_FLOOR);
829	        }
830	        if (!AMOUNT.matcher(value).matches()) {
831	            throw new InvalidSettingException("The floor must be 0.00 or more, with at most two decimals, or blank.");
832	        }
833	        return new Floor(new BigDecimal(value).setScale(2));
834	    }
835	}
