package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * What an overdue claim is charged: the sheet's late percent of its figure for every full 30 days it is overdue
 * (its due-by, fixed when it was created, before the sheet's today), rounded like the claim's due. Never bound by a statement:
 * it follows the sheet's today until the claim is settled. A correction is never charged.
 */
public record LateCharge(BigDecimal pct, LocalDate today) {

    /** The days in each period an overdue claim is charged for. */
    public static final int PERIOD_DAYS = 30;

    /** The charge on the claim's figure (null: n/a, charged nothing); zero unless the claim is overdue. */
    public BigDecimal on(Claim claim, BigDecimal figure, RoundingMode mode) {
        if (figure == null || !claim.status().open() || claim.correction()) {
            return BigDecimal.ZERO.setScale(2);
        }
        long late = ChronoUnit.DAYS.between(claim.dueBy(), today);
        long periods = late > 0 ? late / PERIOD_DAYS : 0;
        return Claim.due(figure, pct.multiply(BigDecimal.valueOf(periods)), mode);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * A claim's due as the screen shows it at this moment (null: n/a): its fixed due, else its figure at its person's
 * grade's rate in force on its date, raised to the sheet's floor and rounded by its policy date — or the figure a
 * statement bound it to — plus the late charge it has on the sheet's today, if overdue.
 */
public final class ClaimDueNow {

    private ClaimDueNow() {
    }

    public static BigDecimal of(Claim claim, SheetRepository sheets, PersonRepository people, RateRepository rates,
            SettingRepository settings, ClaimRepository claims) {
        Person person = people.find(claim.sheetId(), claim.personId());
        BigDecimal rate = person == null ? null
                : Rate.inForce(rates.findAll(claim.sheetId()), person.gradeOn(claim.date()), claim.date());
        LocalDate today = sheets.today(claim.sheetId());
        return claim.due(rate, settings.floor(claim.sheetId()), settings.lateCharge(claim.sheetId(), today),
                settings.rounding(claim.sheetId(), today, claims.findForPerson(claim.sheetId(), claim.personId())));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Cap;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * Works out a sheet's figures as the screen shows them: a person's claimed is their counting claims' amounts
 * added up; their due-total those claims' dues (live figures raised to the sheet's floor and rounded by its policy date, plus
 * any late charge on the overdue ones) added up, at most the sheet's cap; n/a when their grade on the sheet's today has no
 * rate there and no counting claim has a figure (kept, or at the rate for the grade in force on its date). Their overdue-total
 * is the dues of their overdue counting claims added up (skipping n/a, not capped). The sheet's totals add these up, skipping n/a.
 */
@Service
public class RollupService {

    private static final String NA = "n/a";

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
    }

    /** The sheet's figures as the store holds them now. */
    public Rollup compute(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Rate> sheetRates = rates.findAll(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        LateCharge late = settings.lateCharge(sheetId, today);
        List<Claim> sheetClaims = claims.findAll(sheetId);
        Rounding rounding = settings.rounding(sheetId, today, sheetClaims);
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.findAll(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean kept = false;
            for (Claim claim : sheetClaims) {
                if (claim.personId() != person.id() || !person.counts(claim)) {
                    continue;
                }
                claimed = claimed.add(claim.amount());
                kept |= claim.keepsFigure();
                BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()), floor, late, rounding);
                if (figure != null) {
                    kept = true;
                    due = due.add(figure);
                    if (claim.overdue(today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            boolean na = Rate.inForce(sheetRates, person.grade(), today) == null && !kept;
            due = Cap.apply(cap, due);
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dueTotal = dueTotal.add(due);
            }
            overdueTotal = overdueTotal.add(overdue);
            figures.put(person.id(), new Rollup.Figures(person.name(), show(claimed), na ? NA : show(due), show(overdue)));
        }
        return new Rollup(figures, show(claimedTotal), show(dueTotal), show(overdueTotal));
    }

    private static String show(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
