        return;
      }
      input.gradeTerms = { ...input.gradeTerms, [g]: value };
    }
    if (touched.latePct) {
      const value = latePct.trim();
      if (value !== '' && !PERCENT.test(value)) {
        setError(`Type a late percent of 0.00 or more, with at most two decimals, or leave it blank for ${DEFAULT_LATE_PCT}.`);
        return;
      }
      input.latePct = value;
    }
    if (touched.policyDate) {
      const value = policyDate.trim();
      if (value !== '' && !DATE.test(value)) {
        setError("Type a policy date as yyyy-MM-dd, or leave it blank for the sheet's today.");
        return;
      }
      input.policyDate = value;
    }
    if (touched.periodNumberingFrom) {
      const value = periodNumberingFrom.trim();
      if (value !== '' && !DATE.test(value)) {
        setError('Type a period numbering from date as yyyy-MM-dd, or leave it blank for off.');
        return;
      }
      input.periodNumberingFrom = value;
    }
    if (touched.cap) {
      const value = cap.trim();
      if (value !== '' && !AMOUNT.test(value)) {
        setError('Type a cap of 0.00 or more, with at most two decimals, or leave it blank for none.');
        return;
      }
      input.cap = value;
    }
    if (
      input.clerkLimit === undefined &&
      input.floor === undefined &&
      input.terms === undefined &&
      input.gradeTerms === undefined &&
      input.latePct === undefined &&
      input.policyDate === undefined &&
      input.periodNumberingFrom === undefined &&
      input.cap === undefined
    )
      return;
    once(() => save.mutateAsync(input));
  };

  return (
    <section data-testid="settings">
      <p>
        Clerk limit: <span data-testid="setting-clerk-limit-current">{settings?.clerkLimit ?? ''}</span>
      </p>
      <p>
        Floor: <span data-testid="setting-floor-current">{settings?.floor ?? ''}</span>
      </p>
      <p>
        Terms (days): <span data-testid="setting-terms-current">{settings?.terms ?? ''}</span>
      </p>
      {GRADES.map((g) => (
        <p key={g}>
          Terms for grade {g} (days):{' '}
          <span data-testid={`setting-terms-${g}-current`}>
            {settings ? (settings.gradeTerms[g] ?? settings.terms) : ''}
          </span>
        </p>
      ))}
      <p>
        Late percent: <span data-testid="setting-late-pct-current">{settings?.latePct ?? ''}</span>
      </p>
      <p>
        Policy date: <span data-testid="setting-policy-date-current">{settings?.policyDate ?? ''}</span>
      </p>
      <p>
        Period numbering from:{' '}
        <span data-testid="setting-period-numbering-from-current">{settings?.periodNumberingFrom ?? ''}</span>
      </p>
      <p>
        Cap: <span data-testid="setting-cap-current">{settings?.cap ?? ''}</span>
      </p>
      <form onSubmit={submit} data-testid="settings-form">
        <input
          data-testid="setting-clerk-limit"
          placeholder="Clerk limit (blank: no limit)"
          value={clerkLimit}
          onFocus={() => setTouched((t) => ({ ...t, clerkLimit: true }))}
          onChange={(e) => {
            setClerkLimit(e.target.value);
            setTouched((t) => ({ ...t, clerkLimit: true }));
            setError('');
          }}
        />
        <input
          data-testid="setting-floor"
          placeholder={`Floor (blank: ${DEFAULT_FLOOR})`}
          value={floor}
          onFocus={() => setTouched((t) => ({ ...t, floor: true }))}
          onChange={(e) => {
            setFloor(e.target.value);
            setTouched((t) => ({ ...t, floor: true }));
            setError('');
          }}
        />
        <input
          data-testid="setting-terms"
          placeholder={`Terms in days (blank: ${DEFAULT_TERMS})`}
          value={terms}
          onFocus={() => setTouched((t) => ({ ...t, terms: true }))}
          onChange={(e) => {
            setTerms(e.target.value);
            setTouched((t) => ({ ...t, terms: true }));
            setError('');
          }}
        />
        {GRADES.map((g) => (
          <input
            key={g}
            data-testid={`setting-terms-${g}`}
            placeholder={`Terms for grade ${g} in days (blank: the sheet's)`}
            value={gradeTerms[g] ?? ''}
            onFocus={() => setTouchedGrades((t) => ({ ...t, [g]: true }))}
            onChange={(e) => {
              setGradeTerms((v) => ({ ...v, [g]: e.target.value }));
              setTouchedGrades((t) => ({ ...t, [g]: true }));
              setError('');
            }}
          />
        ))}
        <input
          data-testid="setting-late-pct"
          placeholder={`Late percent every 30 days overdue (blank: ${DEFAULT_LATE_PCT})`}
          value={latePct}
          onFocus={() => setTouched((t) => ({ ...t, latePct: true }))}
          onChange={(e) => {
            setLatePct(e.target.value);
            setTouched((t) => ({ ...t, latePct: true }));
            setError('');
          }}
        />
        <input
          data-testid="setting-policy-date"
          placeholder="Rounding policy date, yyyy-MM-dd (blank: the sheet's today)"
          value={policyDate}
          onFocus={() => setTouched((t) => ({ ...t, policyDate: true }))}
          onChange={(e) => {
            setPolicyDate(e.target.value);
            setTouched((t) => ({ ...t, policyDate: true }));
            setError('');
          }}
        />
        <input
          data-testid="setting-period-numbering-from"
          placeholder="Period numbering from, yyyy-MM-dd (blank: off)"
          value={periodNumberingFrom}
          onFocus={() => setTouched((t) => ({ ...t, periodNumberingFrom: true }))}
          onChange={(e) => {
            setPeriodNumberingFrom(e.target.value);
            setTouched((t) => ({ ...t, periodNumberingFrom: true }));
            setError('');
          }}
        />
        <input
          data-testid="setting-cap"
          placeholder="Cap on a person's due-total (blank: none)"
          value={cap}
          onFocus={() => setTouched((t) => ({ ...t, cap: true }))}
          onChange={(e) => {
            setCap(e.target.value);
            setTouched((t) => ({ ...t, cap: true }));
            setError('');
          }}
        />
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {error && <span data-testid="settings-error">{error}</span>}
      </form>
    </section>
  );
}
import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';
import { useSheetToday } from '../session/sheetToday';
import { useClaims } from '../claims/claims';

/** A role given to a user name: clerk or steward. A name with none given is a clerk. */
export type UserRole = { user: string; role: string };

/**
 * The sheet's settings as the store holds them: the clerk limit (two decimals; null: no limit), above
 * which a clerk cannot settle a claim, the floor (two decimals), below which no live due goes, the terms
 * (whole days) a claim is due by after its date, the terms set
 * for each grade that has its own (by grade; any other grade uses the sheet's terms), the late percent (two decimals) an overdue claim
 * gains of its figure every full 30 days, the rounding policy date (yyyy-MM-dd; '': blank, the
 * sheet's today), the period numbering from date (yyyy-MM-dd; '': off — on or after it, an opened claim is
 * numbered within its period), the cap (two decimals; '': none — a person's due-total is at most it), and the roles
 * given to user names.
 */
export type Settings = { clerkLimit: string | null; floor: string; terms: number; gradeTerms: Record<string, number>; latePct: string; policyDate: string; periodNumberingFrom: string; cap: string; roles: UserRole[] };

/** The floor a sheet starts with: a claim's live due is at least it. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days: a claim is due by its date plus them. */
export const DEFAULT_TERMS = 14;

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The roles a user name can be given. */
export const ROLES = ['clerk', 'steward'];

/** 0.00 or more, with at most two decimals. */
export const AMOUNT = /^(\d{1,13}(\.\d{1,2})?|\.\d{1,2})$/;

/** A percent: 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** 0 or more whole days. */
export const DAYS = /^\d{1,5}$/;

/** The query key for the sheet's settings; under sheetKey, so re-loading the sheet re-reads them. */
export const settingsKey = (sheet: string) => [...sheetKey(sheet), 'settings'] as const;

/** The sheet's settings. */
export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: !!sheet,
  });
}

/** The sheet's floor (two decimals): a claim's live due is at least it. */
export function useFloor(): string {
  return useSettings().data?.floor ?? DEFAULT_FLOOR;
}


/** A date as the settings form takes it: yyyy-MM-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * What a claim's due is worked out from: the sheet's floor, late percent and today, its policy
 * date in force (blank: today), its cap ('': none) and the dates of its claims by number (a correction rounds by the date
 * of the claim it corrects).
 */
export type DueRules = {
  floor: string;
  latePct: string;
  today: string;
  policyDate: string;
  cap: string;
  claimDates: Map<string, string>;
};

/** The sheet's rules for working out a claim's due. */
export function useDueRules(): DueRules {
  const settings = useSettings().data;
  const today = useSheetToday();
  const claims = useClaims().data;
  const claimDates = useMemo(
    () => new Map((claims ?? []).filter((c) => c.number !== null).map((c) => [c.number!, c.date])),
    [claims],
  );
  return {
    floor: settings?.floor ?? DEFAULT_FLOOR,
    latePct: settings?.latePct ?? DEFAULT_LATE_PCT,
    today,
    policyDate: settings?.policyDate || today,
    cap: settings?.cap ?? '',
    claimDates,
  };
}
